package app.studyflow;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static app.studyflow.Domain.*;
class EngineTest {
    static final Instant NOW=Instant.parse("2026-11-19T12:00:00Z");
    static Assessment task(String id,double hours,Double weight,Instant due) { return new Assessment(id,"c",id,Kind.ASSIGNMENT,due==null?null:due.toString(),weight,null,null,hours,0,Status.NOT_STARTED,"","manual","",false); }
    static Preferences prefs(int start,int end,List<Integer> days) {return new Preferences("UTC",start,end,50,10,days,30,false,22,8);}
    @Test void urgencyMatters(){var e=new PriorityEngine();assertEquals("soon",e.rank(List.of(task("later",2,10.0,NOW.plusSeconds(86400*8)),task("soon",2,10.0,NOW.plusSeconds(3600))),NOW,3).getFirst().assessment().id());}
    @Test void impactMatters(){var list=new PriorityEngine().rank(List.of(task("low",2,2.0,NOW.plusSeconds(86400)),task("high",2,20.0,NOW.plusSeconds(86400))),NOW,3);assertEquals("high",list.getFirst().assessment().id());}
    @Test void missingWeightIsExplained(){var r=new PriorityEngine().rank(List.of(task("a",2,null,null)),NOW,3).getFirst();assertTrue(r.reasons().stream().anyMatch(s -> s.contains("unknown")));assertTrue(Double.isFinite(r.score()));}
    @Test void pointsAreNotGradeWeight(){Assessment a=new Assessment("a","c","a",Kind.QUIZ,null,null,90.0,100.0,2,0,Status.NOT_STARTED,"","manual","",false);assertEquals(new PriorityEngine().rank(List.of(task("b",2,null,null)),NOW,3).getFirst().score(),new PriorityEngine().rank(List.of(a),NOW,3).getFirst().score());}
    @ParameterizedTest @EnumSource(value=Status.class,names={"COMPLETED","SUBMITTED"}) void completedExcluded(Status status){var a=new Assessment("a","c","a",Kind.LAB,null,null,null,null,2,2,status,"","manual","",false);assertTrue(new PriorityEngine().rank(List.of(a),NOW,3).isEmpty());}
    @ParameterizedTest @EnumSource(Kind.class) void typeDoesNotBias(Kind type){var a=new Assessment("a","c","a",type,null,5.0,null,null,2,0,Status.NOT_STARTED,"","manual","",false);assertEquals(new PriorityEngine().rank(List.of(task("b",2,5.0,null)),NOW,3).getFirst().score(),new PriorityEngine().rank(List.of(a),NOW,3).getFirst().score());}
    @Test void deterministicTies(){assertEquals("a",new PriorityEngine().rank(List.of(task("b",1,null,null),task("a",1,null,null)),NOW,3).getFirst().assessment().id());}
    @Test void boundedScores(){for(int hours=-100;hours<500;hours++) {double n=new PriorityEngine().rank(List.of(task("a",1000,100.0,NOW.plusSeconds(hours*3600L))),NOW,.25).getFirst().score();assertTrue(n>=0 && n<=100);}}
    @Test void invalidWeights(){assertThrows(IllegalArgumentException.class,()->new PriorityEngine.Weights(-1,1,1,1));assertThrows(IllegalArgumentException.class,()->new PriorityEngine.Weights(0,0,0,0));}
    @ParameterizedTest @ValueSource(doubles={-1,101,Double.NaN,Double.POSITIVE_INFINITY}) void invalidGradeWeight(double weight){assertThrows(IllegalArgumentException.class,()->task("a",2,weight,null));}
    @Test void invalidProgress(){assertThrows(IllegalArgumentException.class,()->new Assessment("a","c","title",Kind.LAB,null,null,null,null,2,3,Status.IN_PROGRESS,"","manual","",false));}
    @Test void invalidDate(){assertThrows(Exception.class,()->new Assessment("a","c","title",Kind.LAB,"tomorrow",null,null,null,2,0,Status.NOT_STARTED,"","manual","",false));}
    @Test void scheduleRespectsDeadlinesBreaksAndCapacity(){var tasks=List.of(task("a",2,20.0,NOW.plusSeconds(4*3600)),task("b",4,5.0,NOW.plusSeconds(4*3600)));var plan=new Scheduler().plan(new PriorityEngine().rank(tasks,NOW,4),List.of(),prefs(12,16,List.of(4)),NOW,1);assertFalse(plan.sessions().isEmpty());for(var s:plan.sessions()){assertFalse(Instant.parse(s.start()).isBefore(NOW));assertFalse(Instant.parse(s.end()).isAfter(NOW.plusSeconds(4*3600)));}for(int i=1;i<plan.sessions().size();i++)assertTrue(Duration.between(Instant.parse(plan.sessions().get(i-1).end()),Instant.parse(plan.sessions().get(i).start())).toMinutes()>=10);assertFalse(plan.unscheduled().isEmpty());}
    @Test void pinnedSessionsPreservedWithoutOverlap(){var pinned=new Session("pin","a","a","2026-11-19T13:00:00Z","2026-11-19T14:00:00Z",true);var tasks=List.of(task("a",3,null,NOW.plusSeconds(86400)));var p=new Scheduler().plan(new PriorityEngine().rank(tasks,NOW,4),List.of(pinned),prefs(12,17,List.of(4)),NOW,1);assertTrue(p.sessions().contains(pinned));for(int i=1;i<p.sessions().size();i++)assertFalse(Instant.parse(p.sessions().get(i).start()).isBefore(Instant.parse(p.sessions().get(i-1).end())));double duration=p.sessions().stream().mapToDouble(s->Duration.between(Instant.parse(s.start()),Instant.parse(s.end())).toMinutes()/60.0).sum();assertEquals(3,duration,.02);}
    @Test void overdueWorkIsUnscheduled(){var p=new Scheduler().plan(new PriorityEngine().rank(List.of(task("a",2,null,NOW.minusSeconds(1))),NOW,3),List.of(),prefs(12,16,List.of(4)),NOW,1);assertTrue(p.sessions().isEmpty());assertEquals(2,p.unscheduled().getFirst().hours());}
    @Test void unavailableDaysNotScheduled(){var p=new Scheduler().plan(new PriorityEngine().rank(List.of(task("a",2,null,null)),NOW,3),List.of(),prefs(12,16,List.of(1)),NOW,1);assertTrue(p.sessions().isEmpty());}
    @Test void dstUsesWallClockAvailability(){Instant now=Instant.parse("2026-03-08T05:00:00Z");var pref=new Preferences("America/Toronto",8,10,50,10,List.of(7),30,false,22,8);var p=new Scheduler().plan(new PriorityEngine().rank(List.of(task("a",1,null,null)),now,3),List.of(),pref,now,1);assertEquals(8,Instant.parse(p.sessions().getFirst().start()).atZone(ZoneId.of(pref.zone())).getHour());}
    @Test void gradesUseWeightedContributions(){var a=new Assessment("a","c","a",Kind.LAB,null,40.0,80.0,100.0,2,0,Status.COMPLETED,"","manual","",false);var b=task("b",2,60.0,null);var g=new GradeEngine().calculate("c",List.of(a,b),80);assertEquals(32,g.earnedContribution());assertEquals(80,g.averageOnGradedWork());assertEquals(80,g.requiredOnRemaining());}
    @Test void incompleteSchemeDoesNotPredict(){var g=new GradeEngine().calculate("c",List.of(task("a",2,20.0,null)),80);assertNull(g.requiredOnRemaining());}
    @Test void overweightSchemeIsFlagged(){var g=new GradeEngine().calculate("c",List.of(task("a",2,60.0,null),task("b",2,60.0,null)),80);assertNull(g.requiredOnRemaining());assertTrue(g.note().contains("exceed"));}
    @Test void aiFailureFallsBack(){var service=new AssistantService();service.enable((q,c)->{throw new java.io.IOException("secret must not escape");});var answer=service.answer("What next?",new PriorityEngine().rank(List.of(task("a",2,null,null)),NOW,3),List.of());assertFalse(answer.cloud());assertTrue(answer.notice().contains("unavailable"));assertFalse(answer.text().contains("secret"));}
    @Test void aiContextExcludesNotes(){var service=new AssistantService();service.enable((q,c)->{assertFalse(c.contains("private note"));return "ok";});var a=new Assessment("a","c","a",Kind.LAB,null,null,null,null,2,0,Status.NOT_STARTED,"private note","manual","",false);assertTrue(service.answer("next",new PriorityEngine().rank(List.of(a),NOW,3),List.of()).cloud());}
}
